'use strict';
const local={get(k,fallback){try{return JSON.parse(localStorage.getItem('caisik-'+k))??fallback}catch{return fallback}},set(k,v){try{localStorage.setItem('caisik-'+k,JSON.stringify(v));return true}catch{return false}}};let toastTimer;function toast(message){const el=document.querySelector('.toast');el.textContent=message;el.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.hidden=true,3500)}function download(name,text,type='text/plain'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)}
let saved=local.get('wishlist',[]).filter(x=>collections.some(c=>c.id===x));function syncWish(){document.querySelector('#wish-count').textContent=saved.length;document.querySelectorAll('[data-save]').forEach(b=>{const yes=saved.includes(b.dataset.save);b.textContent=yes?'♥ SAVED':'♡ SAVE';b.setAttribute('aria-pressed',String(yes))})}function toggleWish(id){saved=saved.includes(id)?saved.filter(x=>x!==id):[...saved,id];const ok=local.set('wishlist',saved);syncWish();toast(ok?'Wishlist updated in this browser.':'Wishlist updated for this visit; browser storage is unavailable.')}function addSaveButtons(){document.querySelectorAll('.product-card').forEach(el=>{if(el.querySelector('[data-save]'))return;const id=el.querySelector('[data-detail]').dataset.detail;const b=document.createElement('button');b.className='save-button';b.dataset.save=id;el.appendChild(b)});syncWish()}addSaveButtons();new MutationObserver(addSaveButtons).observe(products,{childList:true});document.addEventListener('click',e=>{const b=e.target.closest('[data-save]');if(b)toggleWish(b.dataset.save)});document.querySelector('#wishlist-open').onclick=()=>open(`<span class="eyebrow">SAVED IN THIS BROWSER / ${saved.length} COLLECTIONS</span><h2>YOUR INNER WORLD.</h2>${saved.length?`<div class="saved-grid">${collections.filter(x=>saved.includes(x.id)).map(x=>`<div><img src="/assets/${x.id}.svg" alt="${x.name} concept"><h3>${x.name}</h3><button class="text-button" data-save="${x.id}">REMOVE FROM SAVED</button><a class="text-button" href="https://hiphop.caisik.i234.me/dk/store?page=1">CHECK LIVE CATALOG ↗</a></div>`).join('')}</div>`:'<p>Your collection is empty. Use SAVE below a design to keep it here. These are concept collections, not purchasable SKUs.</p>'}`);
let simple=local.get('simple',false)||motion.matches;function applySimple(){document.body.classList.toggle('simple-mode',simple);document.querySelector('#motion-toggle').textContent=simple?'SIMPLE':'CINEMATIC';document.querySelector('#motion-toggle').setAttribute('aria-pressed',String(simple));chapters.forEach((el,i)=>{el.inert=simple?false:i!==lastChapter});if(simple){document.querySelector('.hero-art').style.transform='none';document.querySelector('.hero-graffiti').style.translate='none'}else{lastChapter=-1;requestMotion()}}applySimple();document.querySelector('#motion-toggle').onclick=()=>{if(motion.matches&&!simple){simple=true}else if(motion.matches){toast('Your system requests reduced motion. Simple mode stays enabled.');return}else simple=!simple;local.set('simple',simple);applySimple()};motion.addEventListener('change',()=>{if(motion.matches){simple=true;applySimple()}});
let day=local.get('day',false);function applyDay(){document.body.classList.toggle('day-mode',day);document.querySelector('#theme-toggle').setAttribute('aria-pressed',String(day));document.querySelector('#theme-toggle').textContent=day?'NIGHT MODE':'DAY MODE'}applyDay();document.querySelector('#theme-toggle').onclick=()=>{day=!day;local.set('day',day);applyDay()};
let audio=null;document.querySelector('#sound-toggle').onclick=async()=>{if(audio){await audio.close();audio=null;document.querySelector('#sound-toggle').textContent='SOUND OFF';document.querySelector('#sound-toggle').setAttribute('aria-pressed','false');return}try{const AudioCtx=window.AudioContext||window.webkitAudioContext;audio=new AudioCtx();await audio.resume();const gain=audio.createGain();gain.gain.value=.018;gain.connect(audio.destination);[55,82.41,110].forEach((f,i)=>{const o=audio.createOscillator();o.type=i?'sine':'triangle';o.frequency.value=f;o.connect(gain);o.start()});document.querySelector('#sound-toggle').textContent='SOUND ON';document.querySelector('#sound-toggle').setAttribute('aria-pressed','true')}catch{audio=null;toast('Audio is unavailable in this browser.')}};document.addEventListener('visibilitychange',()=>{if(audio){if(document.hidden)audio.suspend();else audio.resume()}});
const viewer=document.querySelector('#viewer-garment');function updateViewer(){const angle=Number(document.querySelector('#viewer-angle').value),zoom=Number(document.querySelector('#viewer-zoom').value)/100,light=Number(document.querySelector('#viewer-light').value)/100;viewer.style.transform=`rotateY(${angle}deg) scale(${zoom})`;viewer.style.filter=`brightness(${light}) drop-shadow(0 25px 30px #0009)`}['viewer-angle','viewer-light','viewer-zoom'].forEach(id=>document.getElementById(id).oninput=updateViewer);document.querySelector('#viewer-collection').onchange=e=>{viewer.src=`/assets/${e.target.value}.svg`;viewer.alt=`Illustrative ${e.target.value} garment concept`};document.querySelector('#decode-open').onclick=()=>open(`<span class="eyebrow">READ THE SYMBOL / ARTWORK INTERPRETATION</span><h2>A LANGUAGE<br>IN THE LINES.</h2><div class="decode-grid"><div><b>△ / THE ASCENT</b><p>Our upward triangle represents intention: a movement toward something you choose.</p></div><div><b>▽ / THE RETURN</b><p>The mirrored triangle invites reflection. An inner world meeting an outer one.</p></div><div><b>○ / THE CYCLE</b><p>The circle frames the design as an ongoing practice rather than a finished identity.</p></div><div><b>GOLD / CHROME / OXIDE</b><p>Three visual directions: inquiry, introspection and transformation. These meanings are this collection’s creative interpretation.</p></div></div>`);document.querySelector('#compare-open').onclick=()=>open(`<h2>THREE WORLDS.</h2><div class="compare-table"><table><thead><tr><th>Collection</th><th>Idea</th><th>Accent</th></tr></thead><tbody>${collections.map((x,i)=>`<tr><td>${x.name}</td><td>${['Inquiry','Introspection','Transformation'][i]}</td><td>${['Antique gold','Chrome','Oxide red'][i]}</td></tr>`).join('')}</tbody></table></div><p>These are design directions. Fit, fabric, printing, price and availability remain unverified until linked to real products.</p>`);
const labScenes=[['MENTALISM','IT STARTS WITH YOUR VIEW.','Move the control to turn the same symbol. A different angle changes what you notice.','Perspective','CHANGE YOUR PERSPECTIVE'],['CORRESPONDENCE','WITHIN. WITHOUT.','Two forms mirror one movement. Explore the relationship between the upper and lower worlds.','Mirror distance','AS ABOVE / SO BELOW'],['VIBRATION','NOTHING STANDS STILL.','Change the visual frequency. This is a geometric metaphor, not a physical frequency measurement.','Frequency','FIND YOUR FREQUENCY'],['POLARITY','HOLD BOTH SIDES.','Move between light and shadow. Notice the shared geometry beneath the change.','Light / shadow','OPPOSITES / ONE STRUCTURE'],['RHYTHM','MOVE. RETURN. REPEAT.','Move the pendulum through an arc. Observe the turn and the return.','Pendulum phase','EVERY MOVEMENT HAS A RETURN'],['CAUSE & EFFECT','ONE MOVE. MANY ECHOES.','Your input unfolds a chain of visible steps. Change the beginning and watch what follows.','Chain progress','WHAT ARE YOU SETTING IN MOTION?'],['CREATION','MAKE SOMETHING REAL.','Combine the shapes into a personal mark. This creative interpretation does not make a biological or scientific claim.','Composition','TURN AN IDEA INTO A FORM']];let labIndex=0;const labSymbol=document.querySelector('#lab-symbol');document.querySelector('#lab-tabs').innerHTML=labScenes.map((p,i)=>`<button data-lab="${i}" class="${i===0?'selected':''}" aria-pressed="${i===0}">${principles[i][0]} / ${p[0]}</button>`).join('');function paintLab(){const v=Number(document.querySelector('#lab-control').value),t=v/100;labSymbol.style.setProperty('--phase',t);labSymbol.style.setProperty('--turn',`${v*3.6}deg`);labSymbol.style.setProperty('--spread',`${10+t*80}px`);labSymbol.style.setProperty('--swing',`${(t-.5)*100}deg`);labSymbol.style.setProperty('--ink',`${35+t*50}%`);labSymbol.querySelectorAll('.lab-chain i').forEach((x,i)=>{x.style.opacity=t>i/5?'1':'.15';x.style.transform=`translateY(${t>i/5?-12:0}px)`})}function chooseLab(i){labIndex=i;const s=labScenes[i];labSymbol.dataset.scene=String(i);document.querySelector('#lab-name').textContent=`${principles[i][0]} / ${s[0]}`;document.querySelector('#lab-title').textContent=s[1];document.querySelector('#lab-description').textContent=s[2];document.querySelector('#lab-label').textContent=s[3];document.querySelector('#lab-visual-caption').textContent=s[4];document.querySelectorAll('[data-lab]').forEach(b=>{b.classList.toggle('selected',Number(b.dataset.lab)===i);b.setAttribute('aria-pressed',String(Number(b.dataset.lab)===i))});document.querySelector('#lab-control').value='50';paintLab()}document.querySelectorAll('[data-lab]').forEach(b=>b.onclick=()=>chooseLab(Number(b.dataset.lab)));document.querySelector('#lab-control').oninput=paintLab;chooseLab(0);
function escapeXml(s){return s.replace(/[<>&"']/g,c=>({'<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;',"'":'&apos;'}[c]))}document.querySelector('#principle-card').onclick=()=>{const s=labScenes[labIndex];download(`caisik-${s[0].toLowerCase()}.svg`,`<svg xmlns="http://www.w3.org/2000/svg" width="1080" height="1350" viewBox="0 0 1080 1350"><rect width="1080" height="1350" fill="#141710"/><g fill="none" stroke="#bca879" stroke-width="3"><circle cx="540" cy="570" r="290"/><path d="M540 270 800 720H280Z M540 870 280 420H800Z"/></g><g fill="#e6e3da" font-family="Arial" text-anchor="middle"><text x="540" y="160" font-size="70" font-weight="bold">CAISIK</text><text x="540" y="990" font-size="40">${escapeXml(s[0])}</text><text x="540" y="1080" font-size="22">${escapeXml(s[4])}</text><text x="540" y="1230" font-size="18" letter-spacing="5">UNDERGROUND ALCHEMY</text></g></svg>`,'image/svg+xml');toast('Your principle card is downloaded.')};
let quizAnswers=[];const questions=[['WHAT DRAWS YOU IN?',['Understanding patterns','Looking inward','Making a change']],['WHICH ATMOSPHERE FEELS YOURS?',['Gold geometry','Chrome and shadow','Oxide and concrete']],['WHAT DO YOU WANT TO CARRY?',['A question','A mirror','A new beginning']]];function drawQuiz(){const n=quizAnswers.length;if(n===3){const counts=[0,0,0];quizAnswers.forEach(a=>counts[a]++);const index=counts.indexOf(Math.max(...counts)),c=collections[index];open(`<span class="eyebrow">YOUR CHOICE / NOT A PERSONALITY DIAGNOSIS</span><h2>${c.name}</h2><p>${c.description}</p><img class="quiz-result" src="/assets/${c.id}.svg" alt="${c.name} concept"><button class="button" data-save="${c.id}">♡ SAVE COLLECTION</button><button class="text-button" id="quiz-restart">START AGAIN</button>`);document.querySelector('#quiz-restart').onclick=()=>{quizAnswers=[];drawQuiz()};return}const q=questions[n];open(`<span class="eyebrow">FIND YOUR WORLD / ${n+1} OF 3</span><h2>${q[0]}</h2><div class="quiz-options">${q[1].map((a,i)=>`<button data-answer="${i}">${a} ↗</button>`).join('')}</div><p>Your choices stay in this session and recommend a visual collection.</p>`);document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{quizAnswers.push(Number(b.dataset.answer));drawQuiz()})}document.querySelector('#quiz-open').onclick=()=>{quizAnswers=[];drawQuiz()};
let album=local.get('album',[]).filter(x=>campaigns.includes(x));function renderAlbum(){document.querySelector('#album-count').textContent=`${album.length} / 12 DISCOVERED`;document.querySelector('#album-grid').innerHTML=campaigns.map((c,i)=>`<a class="album-item ${album.includes(c)?'found':''}" href="/q/${c}"><span>${String(i+1).padStart(2,'0')} / ${album.includes(c)?'DISCOVERED':'ENTER PORTAL'}</span><b>${['✳','△','▽','≈','◐','↔','→','◇','◑','↑','↓','⊕'][i]}</b><strong>${c.replaceAll('-',' ').toUpperCase()}</strong></a>`).join('')}if(path[0]==='q'&&campaigns.includes(path[1])&&!album.includes(path[1])){album.push(path[1]);local.set('album',album)}renderAlbum();document.querySelector('#album-clear').onclick=()=>{album=[];local.set('album',album);renderAlbum();toast('Your local album has been reset.')};if(path[0]==='q'&&campaigns.includes(path[1])){const i=campaigns.indexOf(path[1]);document.querySelector('.portal-symbol').textContent=['✳','△','▽','≈','◐','↔','→','◇','◑','↑','↓','⊕'][i];const message=document.createElement('p');message.className='fineprint';message.textContent=`SIGN ${String(i+1).padStart(2,'0')} / Added to your album in this browser.`;document.querySelector('#portal').appendChild(message);const albumLink=document.createElement('a');albumLink.className='portal-link';albumLink.href='/#album';albumLink.textContent='VIEW MY SYMBOL ALBUM ↗';document.querySelector('#portal').appendChild(albumLink)}
const articles=[['WHY WE CARRY SYMBOLS.','A symbol can hold an idea without finishing the conversation. A circle might suggest continuity. A triangle might suggest direction. The meaning is not fixed by the shape alone: you bring your own experience to it.','The CAISIK collection studies use geometry as an invitation to look again. You do not need to adopt a doctrine to wear a question. Choose a symbol because it opens something for you, not because someone claims it has a secret power.'],['MEETING THE SHADOW.','What do we leave out of the story we tell about ourselves? Shadow Work is the visual theme of this collection: mirrored forms, restrained chrome and a dark ground. It asks for attention rather than a perfect answer.','Here, introspection is a creative subject. The clothing is not a treatment, a diagnosis or a promise of personal transformation. A garment can carry a reminder; the meaning remains yours.'],['FROM THOUGHT TO FORM.','01 / INTENTION — Begin with a short question: what are you becoming? Reduce it to a few visual ideas rather than covering the surface with every possible symbol.','02 / GEOMETRY — Pair an ascending triangle with its reflection. Frame the pair in a circle. Use one accent to give the idea a clear visual voice.','03 / GARMENT — Test the composition against a black silhouette. These images are design studies; real production still requires garment selection, print specifications, samples and quality checks.']];document.querySelectorAll('[data-article]').forEach(b=>b.onclick=()=>{const a=articles[Number(b.dataset.article)];open(`<span class="eyebrow">CAISIK FIELD NOTES / ORIGINAL EDITORIAL</span><h2>${a[0]}</h2>${a.slice(1).map(p=>`<p>${p}</p>`).join('')}`)});
const looks={concrete:['Charcoal layers. Relaxed proportions. A gold symbol against raw concrete.','kybalion'],studio:['Monochrome layers. Silver geometry. A quiet silhouette against a dark studio.','shadow'],oxide:['Black layers. Rust-red accents. A symbol that carries the energy of change.','transmute']};let currentLook='concrete';document.querySelectorAll('[data-style]').forEach(b=>b.onclick=()=>{currentLook=b.dataset.style;const l=looks[currentLook];document.querySelector('.style-scene').dataset.look=currentLook;document.querySelector('.style-scene img').src=`/assets/${l[1]}.svg`;document.querySelector('#style-caption').textContent=l[0];document.querySelector('.style-word').textContent={concrete:'CONCRETE CONSCIOUSNESS.',studio:'MEET YOUR SHADOW.',oxide:'BECOME THE CHANGE.'}[currentLook];document.querySelectorAll('[data-style]').forEach(x=>x.classList.toggle('selected',x===b))});document.querySelector('#style-save').onclick=()=>toggleWish(looks[currentLook][1]);
function showVote(){const v=local.get('vote',null);document.querySelectorAll('[data-vote]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.vote===v)));document.querySelector('#vote-status').textContent=v?`Your local preference: ${v.toUpperCase()}. No community vote has been submitted.`:''}showVote();document.querySelectorAll('[data-vote]').forEach(b=>b.onclick=()=>{local.set('vote',b.dataset.vote);showVote()});document.querySelector('#draft-download').onclick=()=>{const val=document.querySelector('#interpretation').value.trim();if(!val){toast('Write your interpretation first.');return}download('my-caisik-interpretation.txt',`CAISIK — MY INTERPRETATION\n\n${val}\n\nPersonal draft. Not submitted or published.`)};const interests=local.get('interests',[]);document.querySelectorAll('[name=interest]').forEach(x=>x.checked=interests.includes(x.value));document.querySelector('#interests-save').onclick=()=>{const selected=[...document.querySelectorAll('[name=interest]:checked')].map(x=>x.value);const ok=local.set('interests',selected);document.querySelector('#interests-status').textContent=ok?'Saved in this browser. You have not subscribed to email.':'Browser storage unavailable. No preferences saved.'};
const oldPrivacy=document.querySelector('#privacy-open').onclick;document.querySelector('#privacy-open').onclick=()=>{oldPrivacy();const clear=document.createElement('button');clear.className='button';clear.textContent='CLEAR ALL MY LOCAL DATA';clear.onclick=()=>{['wishlist','simple','day','album','vote','interests','product-wishlist'].forEach(k=>{try{localStorage.removeItem('caisik-'+k)}catch{}});document.dispatchEvent(new Event('caisik-clear-local'));saved=[];album=[];syncWish();renderAlbum();toast('Local CAISIK data cleared. Reload to reset appearance.');modal.close()};content.appendChild(clear)};
